using System;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;
public static class CheckV2ClothingScene {
 public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");var scene=SceneManager.GetActiveScene();var root=scene.GetRootGameObjects().Single(x=>x.name=="Ethan_V2_73_Baked");var all=root.GetComponentsInChildren<SkinnedMeshRenderer>(true);var shirt=all.Single(x=>x.name=="BAKED_Outfits_LOD0");var body=all.Single(x=>x.name=="BAKED_body_lod0_mesh");if(shirt.sharedMesh.name!="EthanV2_Outfit_CollarRestored"||body.sharedMesh.name!="EthanV2_Body_ShirtCoverage")throw new Exception("Scene does not inherit repaired mesh assets");var original=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2_73_Baked.fbx").GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name==body.name).sharedMesh;if(body.sharedMesh.vertexCount!=original.vertexCount)throw new Exception("Original body vertex data must be preserved");if(shirt.rootBone!=root.transform||shirt.localBounds.size.x<2)throw new Exception("Incorrect shirt culling frame");var report=new{scene=scene.name,sceneDirty=scene.isDirty,shirt=AssetDatabase.GetAssetPath(shirt.sharedMesh),body=AssetDatabase.GetAssetPath(body.sharedMesh),bodyTriangles=body.sharedMesh.triangles.Length/3,coveredBodyTrianglesHidden=original.triangles.Length/3-body.sharedMesh.triangles.Length/3,originalFullBodyPreserved=original!=body.sharedMesh,runtimeClothingDeformerAbsent=!root.GetComponent<CharacterGarmentSurfaceBinding>(),sameBones=shirt.bones.SequenceEqual(body.bones),shirtCullingRoot=shirt.rootBone.name,shirtBounds=shirt.localBounds.ToString(),oldEthanHidden=!scene.GetRootGameObjects().Single(x=>x.name=="Ethan").activeSelf};System.IO.File.WriteAllText("Data/EthanV2/ClothingRepair/final_scene_verification.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return report;}
}
